// POST ACTION DISPATCHER - Phase 4 Refactoring Integration\r\n
// Replaces 300+ lines of if/elseif statements with pluggable dispatcher\r\n
//=========================================================================\r\n
// Handles all POST actions through registered action handlers:\r\n
// - UnsetTrans, AddCustomer, AddVendor, ToggleTransaction\r\n
// - RunTransferMatcher, RunTransferAudits, ProcessBothSides\r\n
// - ProcessTransaction (main transaction processing)\r\n
//\r\n
// Benefits:\r\n
// - Cognitive complexity reduced from O(n) branches to O(1) dispatch\r\n
// - New actions add easily: create class + register (no controller changes)\r\n
// - Each action encapsulated in single responsibility class\r\n
// - Strategy pattern (TransactionProcessor) integrated seamlessly\r\n
//=========================================================================\r\n
\r\n
try {\r\n
	require_once __DIR__ . '/src/Ksfraser/FaBankImport/Actions/Registry/ActionRegistrar.php';\r\n
	\r\n
	// Create fully initialized dispatcher with all actions registered\r\n
	$actionDispatcher = \Ksfraser\FaBankImport\Actions\Registry\ActionRegistrar::createDispatcher();\r\n
	\r\n
	// Dispatch POST request to first matching action\r\n
	$actionDispatcher->dispatch($_POST);\r\n
	\r\n
} catch (\Throwable $e) {\r\n
	// Log dispatcher errors but don't break page rendering\r\n
	error_log('POST Action Dispatcher error: ' . $e->getMessage());\r\n
	if (function_exists('display_error')) {\r\n
		display_error('An unexpected error occurred processing your request. Please try again.');\r\n
	}\r\n
}\r\n
